script_dir=fileparts(mfilename('fullpath'));root_dir=fileparts(script_dir);w=fullfile(root_dir,'waveforms','10-hall-commutation');a=fullfile(root_dir,'assets','10-hall-commutation');if ~exist(a,'dir');mkdir(a);end
s=readtable(fullfile(w,'plecs_hall_commutation_summary.csv'),'VariableNamingRule','preserve');offsets=s(1:6,:);[~,best_idx]=max(offsets.mean_torque_Nm);best=readtable(fullfile(w,['plecs_offset_' num2str(best_idx-1) '.csv']),'VariableNamingRule','preserve');wrong=readtable(fullfile(w,['plecs_offset_' num2str(mod(best_idx,6)) '.csv']),'VariableNamingRule','preserve');rev=readtable(fullfile(w,'plecs_reverse_table.csv'),'VariableNamingRule','preserve');
fig=figure('Color','w','Position',[100 80 1550 1050]);tl=tiledlayout(fig,3,1,'TileSpacing','compact','Padding','compact');title(tl,'Hall commutation offset sweep and wrong mapping');
nexttile;yyaxis left;bar(offsets.offset_steps,offsets.mean_torque_Nm);ylabel('mean T_e / N m');yyaxis right;plot(offsets.offset_steps,offsets.final_speed_rad_s,'o-','LineWidth',1.4);ylabel('final speed / rad/s');xlabel('commutation offset / 60-deg steps');grid on;
nexttile;plot(best.time_s,best.speed_rad_s,'LineWidth',1.3);hold on;plot(wrong.time_s,wrong.speed_rad_s,'LineWidth',1.3);plot(rev.time_s,rev.speed_rad_s,'LineWidth',1.3);ylabel('\omega_m / rad/s');grid on;legend('best offset','wrong +60 deg','reverse table','Location','eastoutside');
nexttile;plot(best.time_s,best.torque_Nm,'LineWidth',1.0);hold on;plot(wrong.time_s,wrong.torque_Nm,'LineWidth',1.0);plot(rev.time_s,rev.torque_Nm,'LineWidth',1.0);yline(0,':');ylabel('T_e / N m');xlabel('time / s');grid on;
exportgraphics(fig,fullfile(a,'hall_offset_sweep.png'),'Resolution',180);close(fig);fprintf('Generated chapter 10 MATLAB Hall commutation figure. scenarios=%d best_offset=%d\n',height(s),best_idx-1);
